python3 -c 'import csv; from decimal import Decimal, InvalidOperation; from collections import defaultdict; inv=defaultdict(list); pay=defaultdict(list)
for filename,target in [("invoices.csv",inv),("payments.csv",pay)]:
 with open(filename,newline="") as f:
  for line,row in enumerate(csv.DictReader(f),2):
   try:
    amount=Decimal(row["amount"])
    if not amount.is_finite(): raise InvalidOperation
   except InvalidOperation:
    print(filename,"line",line,"invalid amount",repr(row["amount"])); continue
   if not row["invoice_id"]:
    print(filename,"line",line,"missing invoice ID",amount); continue
   target[row["invoice_id"]].append(amount)
for key,amounts in inv.items():
 paid=sum(pay.get(key,[]),Decimal(0))
 if len(amounts)>1: print(key,"AMBIGUOUS invoice rows",amounts,"paid",paid,"single-invoice shortfall",amounts[0]-paid)
 else: print(key,"invoice",amounts[0],"paid",paid,"balance",amounts[0]-paid)
for key,amounts in pay.items():
 if key not in inv: print(key,"unmatched payments",sum(amounts,Decimal(0)))
print("Exact split",Decimal("0.10")+Decimal("0.20"),"binary float",repr(0.10+0.20))'

